def semver_sort(versions):
    def parse_identifier(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def make_key(v):
        core_and_pre = v.split('+', 1)[0]
        parts = core_and_pre.split('-', 1)
        core = parts[0]
        pre = parts[1] if len(parts) > 1 else None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is not None:
            has_pre_flag = 0
            identifiers = pre.split('.')
            ident_keys = [parse_identifier(i) for i in identifiers]
        else:
            has_pre_flag = 1
            ident_keys = []

        return (major, minor, patch, has_pre_flag, ident_keys)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (make_key(pair[1]), pair[0]))
    return [v for _, v in indexed]

